#!/usr/bin/env node
/**
 * Print a fresh VAPID key pair for background web push.
 *
 *   npm run push:keys
 *
 * Generate ONCE and keep the result. The public half is baked into every
 * subscription a browser hands back, so regenerating invalidates all of them:
 * existing rows start failing with 403, the dispatcher deletes them, and every
 * user has to turn push on again.
 */
import webpush from "web-push"

const { publicKey, privateKey } = webpush.generateVAPIDKeys()

process.stdout.write(
  [
    "# Background web push. Generated by `npm run push:keys`.",
    "# Keep these — regenerating invalidates every existing subscription.",
    `VAPID_PUBLIC_KEY="${publicKey}"`,
    `VAPID_PRIVATE_KEY="${privateKey}"`,
    '# Contact address for the push service, if it ever needs to reach you.',
    'VAPID_SUBJECT="mailto:you@example.com"',
    "",
  ].join("\n"),
)
